# Final canonical-position identity.
expected_positions = np.arange(
    logical_length,
    dtype=clean_positions.dtype,
)

if not np.array_equal(
    clean_positions,
    expected_positions,
):
    raise RuntimeError(
        "Global clean_position sequence mismatch."
    )


