def guard_path(path):

    path = Path(path).resolve()

    lower = str(path).lower()

    for marker in FORBIDDEN_MARKERS:
        if marker in lower:
            raise RuntimeError(
                f"PERMANENT HOLDOUT ACCESS BLOCKED: {path}"
            )

    return path


