# 12. CREATE FROZEN TRAIN / VALIDATION MEMMAPS
# =============================================================================

X_train_path = (
    RUNTIME_DIR
    / "X_train_float64.dat"
)

y_train_path = (
    RUNTIME_DIR
    / "y_train_uint8.dat"
)

X_validation_path = (
    RUNTIME_DIR
    / "X_validation_float64.dat"
)

y_validation_path = (
    RUNTIME_DIR
    / "y_validation_uint8.dat"
)

validation_positions_path = (
    RUNTIME_DIR
    / "validation_clean_position_int64.dat"
)


X_train = np.memmap(
    X_train_path,
    dtype=np.float64,
    mode="w+",
    shape=(
        TRAIN_ROWS,
        N_FEATURES,
    ),
)

y_train = np.memmap(
    y_train_path,
    dtype=np.uint8,
    mode="w+",
    shape=(
        TRAIN_ROWS,
    ),
)

X_validation = np.memmap(
    X_validation_path,
    dtype=np.float64,
    mode="w+",
    shape=(
        VALIDATION_ROWS,
        N_FEATURES,
    ),
)

y_validation = np.memmap(
    y_validation_path,
    dtype=np.uint8,
    mode="w+",
    shape=(
        VALIDATION_ROWS,
    ),
)

validation_positions = np.memmap(
    validation_positions_path,
    dtype=np.int64,
    mode="w+",
    shape=(
        VALIDATION_ROWS,
    ),
)


# =============================================================================
# 13. STREAM AUTHORIZED PARQUETS INTO EXACT FROZEN MEMBERSHIPS
# =============================================================================

READ_COLUMNS = (
    [
        "clean_position",
        "binary_label",
    ]
    + FEATURES
)


train_cursor = 0
validation_cursor = 0

materialize_start = time.perf_counter()


print()
print("=" * 96)
print("MATERIALIZING NO_DST_PORT MATRICES")
print("=" * 96)
print()


for day_index, filename in enumerate(
    AUTHORIZED_CACHE_FILES
):

    path = guard_path(
        CACHE_DIR / filename
    )

    parquet = pq.ParquetFile(
        path
    )

    file_rows_seen = 0


    for batch in parquet.iter_batches(
        batch_size=100_000,
        columns=READ_COLUMNS,
        use_threads=True,
    ):

        batch_rows = batch.num_rows

        cp = batch.column(
            batch.schema.get_field_index(
                "clean_position"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.int64,
            copy=False,
        )

        y = batch.column(
            batch.schema.get_field_index(
                "binary_label"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.uint8,
            copy=False,
        )


        # --------------------------------------------------------------
        # Canonical clean_position invariants
        # --------------------------------------------------------------

        expected_global_start = (
            file_rows_seen
            + int(cp[0])
            - file_rows_seen
        )

        if len(cp) == 0:
            continue

        if not np.array_equal(
            cp,
            np.arange(
                int(cp[0]),
                int(cp[0]) + batch_rows,
                dtype=np.int64,
            ),
        ):

            raise RuntimeError(
                f"Non-canonical clean_position sequence in {filename}"
            )


        if int(cp[-1]) >= N_DEVELOPMENT:

            raise RuntimeError(
                f"clean_position exceeds development universe in {filename}"
            )


        is_validation = (
            random_validation_mask[
                cp
            ]
        )

        is_train = (
            ~is_validation
        )


        # --------------------------------------------------------------
        # Predictor matrix in exact frozen subset order
        # --------------------------------------------------------------

        X_batch = np.column_stack([
            batch.column(
                batch.schema.get_field_index(
                    feature
                )
            ).to_numpy(
                zero_copy_only=False
            )
            for feature in FEATURES
        ]).astype(
            np.float64,
            copy=False,
        )


        n_train = int(
            is_train.sum()
        )

        n_validation = int(
            is_validation.sum()
        )


        # --------------------------------------------------------------
        # Train
        # --------------------------------------------------------------

        if n_train:

            next_train = (
                train_cursor
                + n_train
            )

            X_train[
                train_cursor:next_train
            ] = X_batch[
                is_train
            ]

            y_train[
                train_cursor:next_train
            ] = y[
                is_train
            ]

            train_cursor = next_train


        # --------------------------------------------------------------
        # Validation
        # --------------------------------------------------------------

        if n_validation:

            next_validation = (
                validation_cursor
                + n_validation
            )

            X_validation[
                validation_cursor:next_validation
            ] = X_batch[
                is_validation
            ]

            y_validation[
                validation_cursor:next_validation
            ] = y[
                is_validation
            ]

            validation_positions[
                validation_cursor:next_validation
            ] = cp[
                is_validation
            ]

            validation_cursor = (
                next_validation
            )


        file_rows_seen += (
            batch_rows
        )

        del (
            X_batch,
            cp,
            y,
            is_train,
            is_validation,
        )

        gc.collect()


    print(
        f"[OK] day {day_index:02d} "
        f"{filename}"
    )


if train_cursor != TRAIN_ROWS:

    raise RuntimeError(
        "\nTRAIN MATERIALIZATION COUNT MISMATCH\n"
        f"expected: {TRAIN_ROWS:,}\n"
        f"actual  : {train_cursor:,}"
    )


if validation_cursor != VALIDATION_ROWS:

    raise RuntimeError(
        "\nVALIDATION MATERIALIZATION COUNT MISMATCH\n"
        f"expected: {VALIDATION_ROWS:,}\n"
        f"actual  : {validation_cursor:,}"
    )


X_train.flush()
y_train.flush()
X_validation.flush()
y_validation.flush()
validation_positions.flush()


materialize_seconds = (
    time.perf_counter()
    - materialize_start
)


