# =============================================================================
# 20. ENSEMBLE
# =============================================================================

ensemble_float64 = (
    0.5 * lgbm_probability
    + 0.5 * xgb_probability
)


ensemble_probability = np.asarray(
    ensemble_float64,
    dtype=np.float32,
)


if not np.all(
    np.isfinite(
        ensemble_probability
    )
):

    raise RuntimeError(
        "Non-finite ensemble probabilities produced."
    )


# =============================================================================
# 21. METRICS
# =============================================================================

y_val = np.asarray(
    y_validation,
    dtype=np.uint8,
)


attack_prevalence = float(
    y_val.mean()
)


pr_auc = float(
    average_precision_score(
        y_val,
        ensemble_probability,
    )
)


roc_auc = float(
    roc_auc_score(
        y_val,
        ensemble_probability,
    )
)


pr_auc_minus_prevalence = float(
    pr_auc
    - attack_prevalence
)


predicted = (
    ensemble_probability
    >= np.float32(0.50)
).astype(
    np.uint8
)


tn, fp, fn, tp = (
    confusion_matrix(
        y_val,
        predicted,
        labels=[0, 1],
    ).ravel()
)


accuracy = float(
    accuracy_score(
        y_val,
        predicted,
    )
)

precision = float(
    precision_score(
        y_val,
        predicted,
        zero_division=0,
    )
)

recall = float(
    recall_score(
        y_val,
        predicted,
        zero_division=0,
    )
)

f1 = float(
    f1_score(
        y_val,
        predicted,
        zero_division=0,
    )
)

fpr = float(
    fp / (fp + tn)
)

fnr = float(
    fn / (fn + tp)
)


# =============================================================================
# 22. FULL CHRONOLOGICAL REFERENCE
# =============================================================================

full_chrono = json.loads(
    STAGE22_FULL_CHRONO_RESULT.read_text(
        encoding="utf-8"
    )
)


full_pr_auc = float(
    full_chrono[
        "validation_probability"
    ][
        "pr_auc"
    ]
)


full_roc_auc = float(
    full_chrono[
        "validation_probability"
    ][
        "roc_auc"
    ]
)


full_standard = (
    full_chrono[
        "operating_points"
    ][
        "standard"
    ]
)


chrono_pr_penalty = float(
    full_pr_auc
    - pr_auc
)


chrono_roc_penalty = float(
    full_roc_auc
    - roc_auc
)


chrono_f1_penalty = float(
    float(
        full_standard["f1"]
    )
    - f1
)


chrono_recall_penalty = float(
    float(
        full_standard["recall"]
    )
    - recall
)


chrono_fpr_change = float(
    float(
        full_standard["fpr"]
    )
    - fpr
)


