# =============================================================================
# 19. FROZEN 50/50 ENSEMBLE
# =============================================================================

ensemble_float64 = (
    0.5 * lgbm_probability
    + 0.5 * xgb_probability
)


ensemble_probability = np.asarray(
    ensemble_float64,
    dtype=np.float32,
)


if len(
    ensemble_probability
) != VALIDATION_ROWS:

    raise RuntimeError(
        "Ensemble probability length mismatch."
    )


if not np.all(
    np.isfinite(
        ensemble_probability
    )
):

    raise RuntimeError(
        "Non-finite ensemble probabilities produced."
    )


# =============================================================================
# 20. RANKING METRICS
# =============================================================================

y_validation_array = np.asarray(
    y_validation,
    dtype=np.uint8,
)


attack_prevalence = float(
    y_validation_array.mean()
)


pr_auc = float(
    average_precision_score(
        y_validation_array,
        ensemble_probability,
    )
)


roc_auc = float(
    roc_auc_score(
        y_validation_array,
        ensemble_probability,
    )
)


pr_auc_minus_prevalence = float(
    pr_auc
    - attack_prevalence
)


# =============================================================================
# 21. FIXED OPERATING POINT 0.50
# =============================================================================

FIXED_THRESHOLD = np.float32(
    0.50
)


predicted = (
    ensemble_probability
    >= FIXED_THRESHOLD
).astype(
    np.uint8
)


tn, fp, fn, tp = (
    confusion_matrix(
        y_validation_array,
        predicted,
        labels=[0, 1],
    ).ravel()
)


accuracy = float(
    accuracy_score(
        y_validation_array,
        predicted,
    )
)

precision = float(
    precision_score(
        y_validation_array,
        predicted,
        zero_division=0,
    )
)

recall = float(
    recall_score(
        y_validation_array,
        predicted,
        zero_division=0,
    )
)

f1 = float(
    f1_score(
        y_validation_array,
        predicted,
        zero_division=0,
    )
)


fpr = float(
    fp / (fp + tn)
    if (fp + tn)
    else 0.0
)


fnr = float(
    fn / (fn + tp)
    if (fn + tp)
    else 0.0
)


# =============================================================================
# 22. FROZEN FULL RANDOM REFERENCE
# =============================================================================

full_random = json.loads(
    STAGE22_FULL_RANDOM_RESULT.read_text(
        encoding="utf-8"
    )
)


if full_random["cell"] != "RANDOM_NATURAL":

    raise RuntimeError(
        "Unexpected Stage22R FULL random reference."
    )


full_pr_auc = float(
    full_random[
        "validation_probability"
    ][
        "pr_auc"
    ]
)


full_roc_auc = float(
    full_random[
        "validation_probability"
    ][
        "roc_auc"
    ]
)


full_standard = (
    full_random[
        "operating_points"
    ][
        "standard"
    ]
)


# =============================================================================
