# =============================================================================
#
# Δ_R(S) = FULL_R - SUBSET_R
#
# =============================================================================

pr_auc_removal_penalty = float(
    full_pr_auc
    - pr_auc
)


roc_auc_removal_penalty = float(
    full_roc_auc
    - roc_auc
)


f1_removal_penalty_at_050 = float(
    float(
        full_standard[
            "f1"
        ]
    )
    - f1
)


recall_removal_penalty_at_050 = float(
    float(
        full_standard[
            "recall"
        ]
    )
    - recall
)


fpr_change_full_minus_ablated_at_050 = float(
    float(
        full_standard[
            "fpr"
        ]
    )
    - fpr
)


