def guard_path(path):

    path = Path(path).resolve()
    text = str(path).lower()

    for marker in FORBIDDEN_MARKERS:

        if marker in text:
            raise RuntimeError(
                "\nPERMANENT STAGE23 HOLDOUT ACCESS BLOCKED\n"
                f"path   : {path}\n"
                f"marker : {marker}"
            )

    return path


