# =============================================================================

READ_COLUMNS = (
    [
        "clean_position",
        "binary_label",
    ]
    + FEATURES
)


train_cursor = 0
validation_cursor = 0
expected_next_clean_position = 0

materialize_start = (
    time.perf_counter()
)


print()
print("=" * 96)
print("MATERIALIZING RANDOM NO_FWD_SEG_SIZE_MIN MATRICES")
print("=" * 96)
print()


for day_index, filename in enumerate(
    AUTHORIZED_CACHE_FILES
):

    path = guard_path(
        CACHE_DIR
        / filename
    )

    parquet = pq.ParquetFile(
        path
    )

    file_rows = 0


    for batch in parquet.iter_batches(
        batch_size=100_000,
        columns=READ_COLUMNS,
        use_threads=True,
    ):

        batch_rows = batch.num_rows

        if batch_rows == 0:
            continue


        cp = batch.column(
            batch.schema.get_field_index(
                "clean_position"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.int64,
            copy=False,
        )


        y = batch.column(
            batch.schema.get_field_index(
                "binary_label"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.uint8,
            copy=False,
        )


        expected_cp = np.arange(
            expected_next_clean_position,
            expected_next_clean_position
            + batch_rows,
            dtype=np.int64,
        )


        if not np.array_equal(
            cp,
            expected_cp,
        ):
            raise RuntimeError(
                "\nCanonical clean_position mismatch.\n"
                f"file     : {filename}\n"
                f"expected : {expected_next_clean_position:,}\n"
                f"actual   : {int(cp[0]):,}"
            )


        expected_next_clean_position += (
            batch_rows
        )


        is_validation = (
            random_validation_mask[
                cp
            ]
        )

        is_train = ~is_validation


        X_batch = np.column_stack([
            batch.column(
                batch.schema.get_field_index(
                    feature
                )
            ).to_numpy(
                zero_copy_only=False
            )
            for feature in FEATURES
        ]).astype(
            np.float64,
            copy=False,
        )


        n_train = int(
            is_train.sum()
        )

        n_validation = int(
            is_validation.sum()
        )


        if n_train:

            next_train = (
                train_cursor
                + n_train
            )

            if next_train > TRAIN_ROWS:
                raise RuntimeError(
                    "Training memmap overflow."
                )


            X_train[
                train_cursor:next_train
            ] = X_batch[
                is_train
            ]

            y_train[
                train_cursor:next_train
            ] = y[
                is_train
            ]

            train_cursor = (
                next_train
            )


        if n_validation:

            next_validation = (
                validation_cursor
                + n_validation
            )

            if next_validation > VALIDATION_ROWS:
                raise RuntimeError(
                    "Validation memmap overflow."
                )


            X_validation[
                validation_cursor:next_validation
            ] = X_batch[
                is_validation
            ]

            y_validation[
                validation_cursor:next_validation
            ] = y[
                is_validation
            ]

            validation_positions[
                validation_cursor:next_validation
            ] = cp[
                is_validation
            ]

            validation_cursor = (
                next_validation
            )


        file_rows += (
            batch_rows
        )


        del (
            X_batch,
            cp,
            y,
            expected_cp,
            is_train,
            is_validation,
        )

        gc.collect()


    print(
        f"[OK] day {day_index:02d} "
        f"{filename} — {file_rows:,} rows"
    )


# =============================================================================
