def guard_path(path):

    path = Path(path).resolve()

    text = str(path).lower()

    for marker in FORBIDDEN_MARKERS:

        if marker in text:

            raise RuntimeError(
                "\nPERMANENT STAGE23 HOLDOUT ACCESS BLOCKED\n"
                f"path   : {path}\n"
                f"marker : {marker}"
            )

    return path


for filename in AUTHORIZED_CACHE_FILES:

    path = guard_path(
        CACHE_DIR
        / filename
    )

    if not path.exists():

        raise RuntimeError(
            f"Authorized cache missing: {path}"
        )


