# =============================================================================
# 14. MATERIALIZE CHRONOLOGICAL MATRICES
# =============================================================================

READ_COLUMNS = (
    [
        "clean_position",
        "day_id",
        "binary_label",
    ]
    + FEATURES
)


train_cursor = 0
validation_cursor = 0

materialize_start = (
    time.perf_counter()
)


print()
print("=" * 96)
print("MATERIALIZING CHRONOLOGICAL NO_FWD_SEG_SIZE_MIN MATRICES")
print("=" * 96)
print()


for expected_day_id, filename in enumerate(
    AUTHORIZED_CACHE_FILES
):

    path = guard_path(
        CACHE_DIR
        / filename
    )

    parquet = pq.ParquetFile(
        path
    )

    file_rows = 0


    for batch in parquet.iter_batches(
        batch_size=100_000,
        columns=READ_COLUMNS,
        use_threads=True,
    ):

        batch_rows = (
            batch.num_rows
        )

        if batch_rows == 0:
            continue


        cp = batch.column(
            batch.schema.get_field_index(
                "clean_position"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.int64,
            copy=False,
        )


        day_ids = batch.column(
            batch.schema.get_field_index(
                "day_id"
            )
        ).to_numpy(
            zero_copy_only=False
        )


        y = batch.column(
            batch.schema.get_field_index(
                "binary_label"
            )
        ).to_numpy(
            zero_copy_only=False
        ).astype(
            np.uint8,
            copy=False,
        )


        unique_days = np.unique(
            day_ids
        )


        if not (
            len(unique_days) == 1
            and int(unique_days[0]) == expected_day_id
        ):

            raise RuntimeError(
                f"day_id mismatch in {filename}: {unique_days}"
            )


        if expected_day_id <= 6:

            expected_cp_start = (
                train_cursor
            )

        else:

            expected_cp_start = (
                TRAIN_ROWS
                + validation_cursor
            )


        expected_cp = np.arange(
            expected_cp_start,
            expected_cp_start
            + batch_rows,
            dtype=np.int64,
        )


        if not np.array_equal(
            cp,
            expected_cp,
        ):

            raise RuntimeError(
                "\nCanonical clean_position mismatch.\n"
                f"file     : {filename}\n"
                f"expected : {expected_cp_start:,}\n"
                f"actual   : {int(cp[0]):,}"
            )


        X_batch = np.column_stack([
            batch.column(
                batch.schema.get_field_index(
                    feature
                )
            ).to_numpy(
                zero_copy_only=False
            )
            for feature in FEATURES
        ]).astype(
            np.float64,
            copy=False,
        )


        if expected_day_id <= 6:

            next_cursor = (
                train_cursor
                + batch_rows
            )

            if next_cursor > TRAIN_ROWS:

                raise RuntimeError(
                    "Training memmap overflow."
                )


            X_train[
                train_cursor:next_cursor
            ] = X_batch

            y_train[
                train_cursor:next_cursor
            ] = y

            train_cursor = (
                next_cursor
            )


        else:

            next_cursor = (
                validation_cursor
                + batch_rows
            )

            if next_cursor > VALIDATION_ROWS:

                raise RuntimeError(
                    "Validation memmap overflow."
                )


            X_validation[
                validation_cursor:next_cursor
            ] = X_batch

            y_validation[
                validation_cursor:next_cursor
            ] = y

            validation_positions[
                validation_cursor:next_cursor
            ] = cp

            validation_cursor = (
                next_cursor
            )


        file_rows += (
            batch_rows
        )


        del (
            X_batch,
            cp,
            day_ids,
            y,
            expected_cp,
        )

        gc.collect()


    print(
        f"[OK] day {expected_day_id:02d} "
        f"{filename} — {file_rows:,} rows"
    )


