print("=" * 100)
print("STAGED CACHE VERIFICATION ARTIFACTS")
print("=" * 100)

for path in staged:
    print(" ", path)


print()

run(
    [
        "git",
        "diff",
        "--cached",
        "--stat",
    ],
    show=True,
)


