def run(cmd, cwd=REPO_DIR, check=True, show=False):

    result = subprocess.run(
        [str(x) for x in cmd],
        cwd=str(cwd),
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    output = (result.stdout or "").strip()

    if show and output:
        print(output)

    if check and result.returncode != 0:

        raise RuntimeError(
            f"Command failed ({result.returncode}): "
            + " ".join(str(x) for x in cmd)
            + ("\n" + output if output else "")
        )

    return output


def sha256_file(path, chunk_size=32 * 1024 * 1024):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            chunk = f.read(chunk_size)

            if not chunk:
                break

            h.update(chunk)

    return h.hexdigest()


def now_utc():

    return datetime.now(
        timezone.utc
    ).isoformat()


def assert_float(name, actual, expected, tolerance=1e-12):

    actual = float(actual)
    expected = float(expected)

    if abs(actual - expected) >= tolerance:

        raise RuntimeError(
            f"\nFrozen {name} differs from Stage23-1J output.\n"
            f"expected: {expected:+.12f}\n"
            f"actual  : {actual:+.12f}"
        )


