def run(cmd, check=True, show=False):
    p = subprocess.run(
        [str(x) for x in cmd],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )
    out = (p.stdout or "").strip()
    if show and out:
        print(out)
    if check and p.returncode != 0:
        raise RuntimeError(out)
    return out


def sha(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        while True:
            b = f.read(32 * 1024 * 1024)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


