batch_state["status"] = "COMPLETE_UNSEALED"
batch_state["fits_completed_in_batch"] = 18
batch_state["stage23_fits_after"] = 44
batch_state["placebo_fits_after"] = 20
batch_state["completed_utc"] = now()
