def now():
    return datetime.now(timezone.utc).isoformat()


def git(*args, show=False):
    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    out = (p.stdout or "").strip()

    if show and out:
        print(out)

    if p.returncode != 0:
        raise RuntimeError(
            f"git {' '.join(map(str, args))} failed:\n{out}"
        )

    return out


def sha256_file(path, chunk=32 * 1024 * 1024):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            b = f.read(chunk)

            if not b:
                break

            h.update(b)

    return h.hexdigest()


def write_json(path, obj):
    path.write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
        ) + "\n",
        encoding="utf-8",
    )


