def now():
    return datetime.now(timezone.utc).isoformat()


def run_git(*args):
    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    out = (p.stdout or "").strip()

    if p.returncode != 0:
        raise RuntimeError(
            f"git {' '.join(map(str, args))} failed:\n{out}"
        )

    return out


def sha256_file(path, chunk=32 * 1024 * 1024):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            b = f.read(chunk)

            if not b:
                break

            h.update(b)

    return h.hexdigest()


def write_json(path, obj):

    path = Path(path)

    tmp = Path(
        str(path) + ".tmp"
    )

    tmp.write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
        ) + "\n",
        encoding="utf-8",
    )

    tmp.replace(path)


def load_json(path):
    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def metric_block(y, probability):

    y = np.asarray(
        y,
        dtype=np.uint8,
    )

    p = np.asarray(
        probability,
        dtype=np.float64,
    )

    prevalence = float(
        y.mean()
    )

    pr_auc = float(
        average_precision_score(
            y,
            p,
        )
    )

    roc_auc = float(
        roc_auc_score(
            y,
            p,
        )
    )

    pred = (
        p >= 0.50
    ).astype(
        np.uint8
    )

    tn, fp, fn, tp = confusion_matrix(
        y,
        pred,
        labels=[0, 1],
    ).ravel()

    return {
        "attack_prevalence":
            prevalence,

        "pr_auc":
            pr_auc,

        "pr_auc_minus_attack_prevalence":
            pr_auc - prevalence,

        "roc_auc":
            roc_auc,

        "accuracy":
            float(
                accuracy_score(
                    y,
                    pred,
                )
            ),

        "precision":
            float(
                precision_score(
                    y,
                    pred,
                    zero_division=0,
                )
            ),

        "recall":
            float(
                recall_score(
                    y,
                    pred,
                    zero_division=0,
                )
            ),

        "f1":
            float(
                f1_score(
                    y,
                    pred,
                    zero_division=0,
                )
            ),

        "fpr":
            float(
                fp / (fp + tn)
            ),

        "fnr":
            float(
                fn / (fn + tp)
            ),

        "tn": int(tn),
        "fp": int(fp),
        "fn": int(fn),
        "tp": int(tp),
    }


