# =============================================================================
# 1. HELPERS
# =============================================================================

def sha256_file(path, chunk=32 * 1024 * 1024):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            block = f.read(chunk)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (p.stdout or "").strip()


