# =============================================================================
# 7. STREAM EXACT COLUMNS FROM AUTHORIZED PARQUETS
# =============================================================================

print()
print("=" * 100)
print("RECONSTRUCTING MINIMAL CACHE")
print("=" * 100)
print()


cursor = 0

t0 = time.perf_counter()


for day_no, (
    filename,
    expected_rows,
) in enumerate(
    AUTHORIZED_DAYS,
    start=1,
):

    path = SOURCE / filename

    day_start = cursor

    print()
    print(
        f"[{day_no}/8] {filename}"
    )


    pf = pq.ParquetFile(
        path
    )


    for batch in pf.iter_batches(
        batch_size=500_000,
        columns=REQUIRED_COLUMNS,
        use_threads=True,
    ):

        n = batch.num_rows

        end = cursor + n


        names = batch.schema.names

        idx = {
            name: names.index(name)
            for name in REQUIRED_COLUMNS
        }


        # Feature conversion semantics:
        # exact float64, little-endian storage.

        x0 = np.asarray(
            batch.column(
                idx["Dst Port"]
            ).to_numpy(
                zero_copy_only=False
            ),
            dtype=np.float64,
        )

        x58 = np.asarray(
            batch.column(
                idx["Init Fwd Win Byts"]
            ).to_numpy(
                zero_copy_only=False
            ),
            dtype=np.float64,
        )

        x61 = np.asarray(
            batch.column(
                idx["Fwd Seg Size Min"]
            ).to_numpy(
                zero_copy_only=False
            ),
            dtype=np.float64,
        )


        y = np.asarray(
            batch.column(
                idx["binary_label"]
            ).to_numpy(
                zero_copy_only=False
            ),
            dtype=np.uint8,
        )


        cp = np.asarray(
            batch.column(
                idx["clean_position"]
            ).to_numpy(
                zero_copy_only=False
            ),
            dtype=np.int64,
        )


        dst_port[
            cursor:end
        ] = x0

        init_win[
            cursor:end
        ] = x58

        seg_min[
            cursor:end
        ] = x61

        labels[
            cursor:end
        ] = y

        clean_position[
            cursor:end
        ] = cp


        cursor = end


        del (
            batch,
            x0,
            x58,
            x61,
            y,
            cp,
        )

        gc.collect()


    day_rows = (
        cursor
        - day_start
    )


    if day_rows != expected_rows:

        raise RuntimeError(
            f"{filename}: streamed {day_rows:,}, "
            f"expected {expected_rows:,}"
        )


    print(
        f"      completed "
        f"{day_rows:,} rows"
    )


if cursor != N:

    raise RuntimeError(
        f"Global row mismatch: {cursor:,} != {N:,}"
    )


dst_port.flush()
init_win.flush()
seg_min.flush()
labels.flush()
clean_position.flush()


build_seconds = (
    time.perf_counter()
    - t0
)


print()
