def calculate_metrics(
    y_true,
    probability,
    threshold=0.5,
):

    y_true = np.asarray(
        y_true,
        dtype=np.uint8,
    )

    probability = np.asarray(
        probability,
        dtype=np.float64,
    )

    prediction = (
        probability
        >= threshold
    ).astype(
        np.uint8
    )


    prevalence = safe_float(
        y_true.mean()
    )

    pr_auc = safe_float(
        average_precision_score(
            y_true,
            probability,
        )
    )

    roc_auc = safe_float(
        roc_auc_score(
            y_true,
            probability,
        )
    )


    tn, fp, fn, tp = (
        confusion_matrix(
            y_true,
            prediction,
            labels=[0, 1],
        )
        .ravel()
        .tolist()
    )


    tn = safe_int(tn)
    fp = safe_int(fp)
    fn = safe_int(fn)
    tp = safe_int(tp)


    fpr = (
        fp / (fp + tn)
        if (fp + tn)
        else 0.0
    )

    fnr = (
        fn / (fn + tp)
        if (fn + tp)
        else 0.0
    )


    metrics = {
        "PR_AUC":
            pr_auc,

        "PR_AUC_MINUS_ATTACK_PREVALENCE":
            pr_auc
            - prevalence,

        "ROC_AUC":
            roc_auc,

        "accuracy":
            safe_float(
                accuracy_score(
                    y_true,
                    prediction,
                )
            ),

        "precision":
            safe_float(
                precision_score(
                    y_true,
                    prediction,
                    zero_division=0,
                )
            ),

        "recall":
            safe_float(
                recall_score(
                    y_true,
                    prediction,
                    zero_division=0,
                )
            ),

        "f1":
            safe_float(
                f1_score(
                    y_true,
                    prediction,
                    zero_division=0,
                )
            ),

        "fpr":
            safe_float(fpr),

        "fnr":
            safe_float(fnr),
    }


    return {
        "attack_prevalence":
            prevalence,

        "operating_threshold":
            safe_float(threshold),

        "metrics":
            metrics,

        "confusion_matrix": {
            "tn": tn,
            "fp": fp,
            "fn": fn,
            "tp": tp,
        },
    }


def class_distribution(
    y,
):
    counts = np.bincount(
        np.asarray(
            y,
            dtype=np.uint8,
        ),
        minlength=2,
    )

    benign = int(
        counts[0]
    )

    attack = int(
        counts[1]
    )

    support = (
        benign + attack
    )

    attack_rate = (
        attack / support
        if support
        else None
    )

    return {
        "benign":
            benign,

        "attack":
            attack,

        "attack_rate":
            (
                safe_float(
                    attack_rate
                )
                if attack_rate
                is not None
                else None
            ),
    }


def extract_tree_structure(
    clf,
    X_train_imputed,
    y_train,
    feature_name,
    median,
):
    tree = clf.tree_

    root_feature = int(
        tree.feature[0]
    )

    # sklearn uses TREE_UNDEFINED = -2 when the root never split.
    split_performed = (
        root_feature >= 0
    )


    if not split_performed:

        root_distribution = (
            class_distribution(
                y_train
            )
        )

        predicts_attack = (
            root_distribution[
                "attack_rate"
            ]
            >= 0.5
        )

        return {
            "selected_feature":
                feature_name,

            "tree_split_performed":
                False,

            "split_threshold":
                None,

            "missing_imputation_median":
                safe_float(
                    median
                ),

            "left_leaf_class_distribution":
                None,

            "right_leaf_class_distribution":
                None,

            "left_leaf_support":
                0,

            "right_leaf_support":
                0,

            "branch_predicting_attack":
                (
                    "NO_SPLIT_ROOT"
                    if predicts_attack
                    else "NEITHER"
                ),

            "root_class_distribution":
                root_distribution,

            "attack_branch_rule":
                (
                    "Attack iff leaf P(y=1) >= 0.5."
                ),
        }


    if root_feature != 0:

        raise RuntimeError(
            "Single-feature stump split on unexpected feature index."
        )


    threshold = safe_float(
        tree.threshold[0]
    )


    x = np.asarray(
        X_train_imputed[
            :,
            0
        ],
        dtype=np.float64,
    )


    left_mask = (
        x <= threshold
    )

    right_mask = (
        ~left_mask
    )


    left_y = (
        y_train[
            left_mask
        ]
    )

    right_y = (
        y_train[
            right_mask
        ]
    )


    left_distribution = (
        class_distribution(
            left_y
        )
    )

    right_distribution = (
        class_distribution(
            right_y
        )
    )


    left_support = int(
        left_mask.sum()
    )

    right_support = int(
        right_mask.sum()
    )


    if (
        left_support
        + right_support
        != len(y_train)
    ):
        raise RuntimeError(
            "Stump leaf support does not sum to training membership."
        )


    # Same decision rule as frozen threshold 0.5.

    left_attack = (
        left_distribution[
            "attack_rate"
        ]
        >= 0.5
    )

    right_attack = (
        right_distribution[
            "attack_rate"
        ]
        >= 0.5
    )


    if (
        left_attack
        and right_attack
    ):
        branch = "BOTH"

    elif left_attack:
        branch = "LEFT"

    elif right_attack:
        branch = "RIGHT"

    else:
        branch = "NEITHER"


    return {
        "selected_feature":
            feature_name,

        "tree_split_performed":
            True,

        "split_threshold":
            threshold,

        "missing_imputation_median":
            safe_float(
                median
            ),

        "left_leaf_class_distribution":
            left_distribution,

        "right_leaf_class_distribution":
            right_distribution,

        "left_leaf_support":
            left_support,

        "right_leaf_support":
            right_support,

        "branch_predicting_attack":
            branch,

        "attack_branch_rule":
            (
                "Attack iff leaf P(y=1) >= 0.5."
            ),

        "sklearn_tree_n_node_samples": {
            "root":
                int(
                    tree.n_node_samples[
                        0
                    ]
                ),

            "left":
                int(
                    tree.n_node_samples[
                        tree.children_left[
                            0
                        ]
                    ]
                ),

            "right":
                int(
                    tree.n_node_samples[
                        tree.children_right[
                            0
                        ]
                    ]
                ),
        },
    }


