# There are NO .fit() calls below.
# =============================================================================

print()
print("=" * 100)
print("DERIVE VALIDATION LEAF DISTRIBUTIONS — ZERO FITS")
print("=" * 100)
print()


labels = np.memmap(
    CACHE
    / "binary_label.uint8.dat",
    dtype=np.uint8,
    mode="r",
    shape=(N,),
)


packed = np.fromfile(
    CACHE
    / "random_validation.packbits",
    dtype=np.uint8,
)

random_val_mask = np.unpackbits(
    packed,
    bitorder="little",
)[:N].astype(
    np.bool_,
    copy=False,
)


result_files = sorted(
    SOURCE.glob(
        "*_result.json"
    )
)


if len(result_files) != 6:
    raise RuntimeError(
        f"Expected exactly six stump result JSONs; found {len(result_files)}"
    )


validation_leaf_report = {
    "stage":
        "Stage23-3 validation leaf distributions",

    "status":
        "ZERO_FIT_DERIVED_SUPPLEMENT",

    "created_utc":
        now(),

    "model_fits":
        0,

    "source_summary_sha256":
        EXPECTED_SUMMARY_SHA,

    "definition":
        (
            "Validation rows are routed through the already-fitted "
            "training-only median imputer and depth-1 stump. "
            "No estimator or imputer is refit."
        ),

    "results":
        [],
}


for result_file in result_files:

    result = json.loads(
        result_file.read_text(
            encoding="utf-8"
        )
    )

    stage = result["stage"]
    feature = result["cell"]["feature"]
    split = result["cell"]["split"]

    index = FEATURE_INDEX[
        feature
    ]


    model_name = (
        result[
            "model"
        ][
            "model_artifact"
        ]
    )

    model_path = (
        SOURCE
        / model_name
    )


    artifact = joblib.load(
        model_path
    )

    imputer = (
        artifact[
            "imputer"
        ]
    )

    stump = (
        artifact[
            "stump"
        ]
    )


    x = np.memmap(
        CACHE
        / "features"
        / f"feature_{index:02d}.float64.dat",
        dtype="<f8",
        mode="r",
        shape=(N,),
    )


    if split == "RANDOM_NATURAL":

        X_val_raw = np.asarray(
            x[
                random_val_mask
            ],
            dtype=np.float64,
        ).reshape(
            -1,
            1,
        )

        y_val = np.asarray(
            labels[
                random_val_mask
            ],
            dtype=np.uint8,
        )


    elif split == "CHRONOLOGICAL_NATURAL":

        X_val_raw = np.asarray(
            x[
                CHRONO_TRAIN_N:
            ],
            dtype=np.float64,
        ).reshape(
            -1,
            1,
        )

        y_val = np.asarray(
            labels[
                CHRONO_TRAIN_N:
            ],
            dtype=np.uint8,
        )


    else:
        raise RuntimeError(
            f"Unexpected split: {split}"
        )


    # TRANSFORM ONLY — no fit.
    X_val = imputer.transform(
        X_val_raw
    )


    tree = stump.tree_

    if int(
        tree.feature[0]
    ) < 0:

        entry = {
            "stage":
                stage,

            "feature":
                feature,

            "split":
                split,

            "split_performed":
                False,

            "validation_root_distribution":
                distribution(
                    y_val
                ),
        }


    else:

        threshold = float(
            tree.threshold[0]
        )

        left = (
            X_val[
                :,
                0
            ]
            <= threshold
        )

        right = ~left


        entry = {
            "stage":
                stage,

            "feature":
                feature,

            "split":
                split,

            "split_performed":
                True,

            "split_threshold":
                threshold,

            "training_imputation_median":
                float(
                    imputer.statistics_[0]
                ),

            "left_validation_leaf":
                distribution(
                    y_val[
                        left
                    ]
                ),

            "right_validation_leaf":
                distribution(
                    y_val[
                        right
                    ]
                ),

            "branch_predicting_attack":
                result[
                    "tree_structure"
                ][
                    "branch_predicting_attack"
                ],
        }


    validation_leaf_report[
        "results"
    ].append(
        entry
    )


    print(
        f"[DERIVED] {stage} — "
        f"{feature} × {split}"
    )


    del (
        artifact,
        imputer,
        stump,
        x,
        X_val_raw,
        X_val,
        y_val,
    )

    gc.collect()


del (
    labels,
    packed,
    random_val_mask,
)

gc.collect()


