def utc_now():
    return datetime.now(
        timezone.utc
    ).isoformat()


def git(*args):
    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            b = f.read(chunk)

            if not b:
                break

            h.update(b)

    return h.hexdigest()


def write_json(
    path,
    obj,
):
    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def parse_manifest(path):

    result = {}

    for line in Path(path).read_text(
        encoding="utf-8"
    ).splitlines():

        if not line.strip():
            continue

        digest, rel = line.split(
            maxsplit=1
        )

        result[
            rel.strip()
        ] = digest.strip()

    return result


def metric_pair(
    y,
    probability,
):
    return (
        float(
            average_precision_score(
                y,
                probability,
            )
        ),
        float(
            roc_auc_score(
                y,
                probability,
            )
        ),
    )


def ci95(values):

    values = np.asarray(
        values,
        dtype=np.float64,
    )

    q = np.percentile(
        values,
        [2.5, 97.5],
    )

    return {
        "lower_2_5":
            float(q[0]),

        "upper_97_5":
            float(q[1]),
    }


def locate_cohort_rows(
    probability_clean_position,
    cohort_clean_position,
):

    cp = np.asarray(
        probability_clean_position,
        dtype=np.int64,
    )

    target = np.asarray(
        cohort_clean_position,
        dtype=np.int64,
    )

    # Fast path if the full validation artifact already contains
    # cohort positions in a searchable canonical order.
    order = np.argsort(
        cp,
        kind="mergesort",
    )

    cp_sorted = cp[
        order
    ]

    loc = np.searchsorted(
        cp_sorted,
        target,
    )

    if np.any(
        loc >= len(cp_sorted)
    ):
        raise RuntimeError(
            "Cohort clean_position not found in validation artifact."
        )

    if not np.array_equal(
        cp_sorted[loc],
        target,
    ):
        raise RuntimeError(
            "Frozen uncertainty cohort does not map exactly "
            "onto validation clean_position."
        )

    original_indices = (
        order[
            loc
        ]
    )

    if not np.array_equal(
        cp[
            original_indices
        ],
        target,
    ):
        raise RuntimeError(
            "clean_position mapping verification failed."
        )

    return original_indices


def get_leaf(
    comparison,
    split,
):

    split_dir = (
        "random"
        if split == "RANDOM_NATURAL"
        else "chronological"
    )

    root = (
        PRIMARY_ROOT
        if comparison["family"] == "PRIMARY"
        else PLACEBO_ROOT
    )

    d = (
        root
        / split_dir
        / comparison["slug"]
    )

    if not d.is_dir():
        raise RuntimeError(
            f"Missing comparison directory: {d}"
        )

    result_files = sorted(
        d.glob(
            "*_result.json"
        )
    )

    probability_files = sorted(
        d.glob(
            "*validation_probabilities.npz"
        )
    )

    if len(result_files) != 1:
        raise RuntimeError(
            f"{d}: expected 1 result JSON; "
            f"found {len(result_files)}"
        )

    if len(probability_files) != 1:
        raise RuntimeError(
            f"{d}: expected 1 probability NPZ; "
            f"found {len(probability_files)}"
        )

    return (
        result_files[0],
        probability_files[0],
    )


def result_point_metrics(
    result_path,
):

    r = json.loads(
        result_path.read_text(
            encoding="utf-8"
        )
    )

    if "ranking_metrics" not in r:
        raise RuntimeError(
            f"ranking_metrics missing: {result_path}"
        )

    return {
        "pr_auc":
            float(
                r[
                    "ranking_metrics"
                ][
                    "pr_auc"
                ]
            ),

        "roc_auc":
            float(
                r[
                    "ranking_metrics"
                ][
                    "roc_auc"
                ]
            ),

        "stage":
            r.get(
                "stage",
                "UNKNOWN",
            ),
    }


def full_result_point_metrics(
    result_path,
):

    r = json.loads(
        result_path.read_text(
            encoding="utf-8"
        )
    )

    vp = (
        r[
            "validation_probability"
        ]
    )

    return {
        "pr_auc":
            float(
                vp[
                    "pr_auc"
                ]
            ),

        "roc_auc":
            float(
                vp[
                    "roc_auc"
                ]
            ),
    }


