def run_split_bootstrap(
    split,
):

    print()
    print("=" * 100)
    print(
        f"BOOTSTRAP — {split}"
    )
    print("=" * 100)
    print()


    y = (
        cohort_data[
            split
        ][
            "y"
        ]
    )

    probabilities = (
        cohort_data[
            split
        ][
            "probabilities"
        ]
    )


    benign_index = np.flatnonzero(
        y == 0
    )

    attack_index = np.flatnonzero(
        y == 1
    )


    expected_benign = (
        43_158
        if split == "RANDOM_NATURAL"
        else 44_758
    )

    expected_attack = (
        6_842
        if split == "RANDOM_NATURAL"
        else 5_242
    )


    assert (
        len(
            benign_index
        )
        == expected_benign
    )

    assert (
        len(
            attack_index
        )
        == expected_attack
    )


    rng = np.random.RandomState(
        BOOTSTRAP_SEED
    )


    full_pr = np.empty(
        BOOTSTRAP_REPLICATES,
        dtype=np.float64,
    )

    full_roc = np.empty(
        BOOTSTRAP_REPLICATES,
        dtype=np.float64,
    )


    pr_penalty = {
        comparison[
            "name"
        ]:
            np.empty(
                BOOTSTRAP_REPLICATES,
                dtype=np.float64,
            )
        for comparison
        in COMPARISONS
    }


    roc_penalty = {
        comparison[
            "name"
        ]:
            np.empty(
                BOOTSTRAP_REPLICATES,
                dtype=np.float64,
            )
        for comparison
        in COMPARISONS
    }


    t0 = time.perf_counter()


    for b in range(
        BOOTSTRAP_REPLICATES
    ):

        # Frozen class-preserving bootstrap.
        #
        # Benign and attack are sampled separately WITH replacement,
        # preserving exact cohort class counts.

        sampled_benign = rng.choice(
            benign_index,
            size=len(
                benign_index
            ),
            replace=True,
        )

        sampled_attack = rng.choice(
            attack_index,
            size=len(
                attack_index
            ),
            replace=True,
        )

        sampled = np.concatenate(
            [
                sampled_benign,
                sampled_attack,
            ]
        )


        y_b = y[
            sampled
        ]


        # FULL once for this split / replicate.

        full_pr_b, full_roc_b = (
            metric_pair(
                y_b,
                probabilities[
                    "FULL"
                ][
                    sampled
                ],
            )
        )


        full_pr[
            b
        ] = full_pr_b

        full_roc[
            b
        ] = full_roc_b


        # SAME sampled membership for every compared ablation.

        for comparison in COMPARISONS:

            name = (
                comparison[
                    "name"
                ]
            )

            ablated_pr_b, ablated_roc_b = (
                metric_pair(
                    y_b,
                    probabilities[
                        name
                    ][
                        sampled
                    ],
                )
            )


            pr_penalty[
                name
            ][
                b
            ] = (
                full_pr_b
                - ablated_pr_b
            )


            roc_penalty[
                name
            ][
                b
            ] = (
                full_roc_b
                - ablated_roc_b
            )


        completed = (
            b + 1
        )


        if (
            completed % 100 == 0
            or completed
            == BOOTSTRAP_REPLICATES
        ):

            elapsed = (
                time.perf_counter()
                - t0
            )

            print(
                f"[{split}] "
                f"{completed:4d}/"
                f"{BOOTSTRAP_REPLICATES} "
                f"replicates complete "
                f"({elapsed:.1f} s)",
                flush=True,
            )


            if split == "RANDOM_NATURAL":

                state[
                    "bootstrap_random_completed"
                ] = completed

            else:

                state[
                    "bootstrap_chronological_completed"
                ] = completed


            state[
                "status"
            ] = (
                f"{split}_BOOTSTRAP_IN_PROGRESS"
                if completed
                < BOOTSTRAP_REPLICATES
                else f"{split}_BOOTSTRAP_COMPLETE"
            )


            write_json(
                STATE_PATH,
                state,
            )


    return {
        "full_pr":
            full_pr,

        "full_roc":
            full_roc,

        "pr_penalty":
            pr_penalty,

        "roc_penalty":
            roc_penalty,
    }


