def utc_now():
    return datetime.now(
        timezone.utc
    ).isoformat()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):
    h = hashlib.sha256()

    with Path(path).open("rb") as f:
        while True:
            block = f.read(chunk)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def write_json(
    path,
    obj,
):
    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def git(
    *args,
    check=True,
    show=False,
):
    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    out = (
        p.stdout or ""
    ).strip()

    if show and out:
        print(out)

    if check and p.returncode != 0:
        raise RuntimeError(
            f"git {' '.join(map(str,args))} failed:\n{out}"
        )

    return p.returncode, out


