def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            block = f.read(
                chunk
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def parse_manifest(path):

    out = {}

    for line in Path(path).read_text(
        encoding="utf-8"
    ).splitlines():

        if not line.strip():
            continue

        digest, rel = line.split(
            maxsplit=1
        )

        out[
            rel.strip()
        ] = digest.strip()

    return out


def find_exact_one(
    directory,
    pattern,
    label,
):

    matches = sorted(
        directory.glob(
            pattern
        )
    )

    if len(matches) != 1:

        raise RuntimeError(
            f"{label}: expected exactly one {pattern} under\n"
            f"{directory}\n"
            f"found={len(matches)}"
        )

    return matches[0]


def normalize_subset_from_dir(
    name,
):

    mapping = {
        "no_dst_port":
            "NO_DST_PORT",

        "no_ports":
            "NO_PORTS",

        "no_init_fwd_win_byts":
            "NO_INIT_FWD_WIN_BYTS",

        "no_fwd_seg_size_min":
            "NO_FWD_SEG_SIZE_MIN",

        "no_suspicious_group":
            "NO_SUSPICIOUS_GROUP",

        "behavior_only":
            "BEHAVIOR_ONLY",

        "placebo_counts":
            "PLACEBO_COUNTS",

        "placebo_volume_direction":
            "PLACEBO_VOLUME_DIRECTION",

        "placebo_iat":
            "PLACEBO_IAT",

        "placebo_packet_size":
            "PLACEBO_PACKET_SIZE",

        "placebo_activity":
            "PLACEBO_ACTIVITY",
    }

    if name not in mapping:
        raise RuntimeError(
            f"Unknown frozen subset directory: {name}"
        )

    return mapping[name]


