def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (p.stdout or "").strip()


