def utc_now():

    return datetime.now(
        timezone.utc
    ).isoformat()


def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            block = f.read(
                chunk
            )

            if not block:
                break

            h.update(
                block
            )

    return h.hexdigest()


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def one(
    directory,
    pattern,
):

    matches = sorted(
        directory.glob(
            pattern
        )
    )

    if len(matches) != 1:

        raise RuntimeError(
            f"Expected exactly one {pattern} under\n"
            f"{directory}\n"
            f"found={len(matches)}"
        )

    return matches[0]


def safe_slug(
    value,
):

    return (
        value
        .lower()
        .replace(
            " ",
            "_",
        )
        .replace(
            "/",
            "_",
        )
    )


