# =============================================================================
# 9. SHAP OUTPUT NORMALIZATION
# =============================================================================

def normalize_binary_shap(
    values,
    n_rows,
    n_features,
):

    extraction_mode = None


    if isinstance(
        values,
        list,
    ):

        # Binary classifier positive-class output if library returns
        # class-specific lists.
        if len(
            values
        ) == 2:

            arr = np.asarray(
                values[
                    1
                ],
                dtype=np.float64,
            )

            extraction_mode = (
                "BINARY_LIST_POSITIVE_CLASS_INDEX_1"
            )

        elif len(
            values
        ) == 1:

            arr = np.asarray(
                values[
                    0
                ],
                dtype=np.float64,
            )

            extraction_mode = (
                "SINGLE_LIST_OUTPUT"
            )

        else:

            raise RuntimeError(
                f"Unexpected SHAP list output count: {len(values)}"
            )


    else:

        arr = np.asarray(
            values,
            dtype=np.float64,
        )


        if arr.ndim == 2:

            extraction_mode = (
                "SINGLE_BINARY_OUTPUT_MATRIX"
            )


        elif (
            arr.ndim == 3
            and arr.shape[
                0
            ] == n_rows
            and arr.shape[
                1
            ] == n_features
            and arr.shape[
                2
            ] == 2
        ):

            arr = arr[
                :,
                :,
                1,
            ]

            extraction_mode = (
                "BINARY_OUTPUT_AXIS_POSITIVE_CLASS_INDEX_1"
            )


        else:

            raise RuntimeError(
                f"Unexpected SHAP ndarray shape: {arr.shape}"
            )


    if arr.shape != (
        n_rows,
        n_features,
    ):

        raise RuntimeError(
            "Normalized SHAP matrix shape mismatch.\n"
            f"expected={(n_rows, n_features)}\n"
            f"actual={arr.shape}"
        )


    if not np.all(
        np.isfinite(
            arr
        )
    ):

        raise RuntimeError(
            "Non-finite SHAP values produced."
        )


    return (
        arr,
        extraction_mode,
    )


# =============================================================================
# 10. DETERMINISTIC IMPORTANCE / RANK HELPERS
# =============================================================================

def ordered_features(
    feature_names,
    importance,
):

    pairs = list(
        zip(
            feature_names,
            importance,
        )
    )


    # Importance descending.
    # Exact ties resolved only by prospectively frozen canonical feature order.

    pairs.sort(
        key=lambda pair: (
            -float(
                pair[
                    1
                ]
            ),
            CANONICAL_POSITION[
                pair[
                    0
                ]
            ],
        )
    )


    return [
        feature
        for feature, _
        in pairs
    ]


def rank_map(
    ordered,
):

    return {
        feature:
            rank
        for rank, feature
        in enumerate(
            ordered,
            start=1,
        )
    }


def jaccard(
    a,
    b,
):

    a = set(
        a
    )

    b = set(
        b
    )

    union = (
        a
        | b
    )


    if not union:

        return 1.0


    return float(
        len(
            a
            & b
        )
        / len(
            union
        )
    )


