def component_checkpoint_path(
    split,
    subset,
    component,
):

    d = (
        COMPONENT_ROOT
        / safe_slug(
            split
        )
        / safe_slug(
            subset
        )
    )

    d.mkdir(
        parents=True,
        exist_ok=True,
    )


    return (
        d
        / (
            safe_slug(
                component
            )
            + "_importance.json"
        )
    )


