# 16. PROXY-ABSORPTION COMPARISON FUNCTION
# =============================================================================

def compare_to_full(
    full_record,
    subset_record,
):

    full_features = set(
        full_record[
            "feature_order"
        ]
    )

    subset_features = set(
        subset_record[
            "feature_order"
        ]
    )


    common = [
        feature
        for feature
        in FULL_FEATURE_ORDER
        if (
            feature
            in full_features
            and feature
            in subset_features
        )
    ]


    if not common:

        raise RuntimeError(
            "No common retained features for proxy-absorption comparison."
        )


    full_rank = full_record[
        "rank"
    ]

    subset_rank = subset_record[
        "rank"
    ]


    full_rank_vector = np.asarray(
        [
            full_rank[
                feature
            ]
            for feature
            in common
        ],
        dtype=np.float64,
    )

    subset_rank_vector = np.asarray(
        [
            subset_rank[
                feature
            ]
            for feature
            in common
        ],
        dtype=np.float64,
    )


    spearman_result = spearmanr(
        full_rank_vector,
        subset_rank_vector,
    )


    spearman_rho = float(
        spearman_result.statistic
    )


    if not np.isfinite(
        spearman_rho
    ):

        raise RuntimeError(
            "Non-finite Spearman rank correlation."
        )


    full_top10 = full_record[
        "top_10_features"
    ]

    subset_top10 = subset_record[
        "top_10_features"
    ]

    full_top20 = full_record[
        "top_20_features"
    ]

    subset_top20 = subset_record[
        "top_20_features"
    ]


    rank_displacement = {
        feature:
            int(
                subset_rank[
                    feature
                ]
                - full_rank[
                    feature
                ]
            )

        for feature
        in common
    }


    normalized_share_change = {
        feature:
            float(
                subset_record[
                    "normalized_importance_share"
                ][
                    feature
                ]
                - full_record[
                    "normalized_importance_share"
                ][
                    feature
                ]
            )

        for feature
        in common
    }


    # No arbitrary K was frozen for "top importance gainers".
    # Therefore retain ALL positive gainers, deterministically sorted.

    positive_gainers = [
        feature
        for feature
        in common
        if normalized_share_change[
            feature
        ] > 0
    ]


    positive_gainers.sort(
        key=lambda feature: (
            -normalized_share_change[
                feature
            ],
            CANONICAL_POSITION[
                feature
            ],
        )
    )


    return {
        "common_retained_feature_count":
            len(
                common
            ),

        "top_10_features":
            subset_top10,

        "top_20_features":
            subset_top20,

        "full_top_10_features":
            full_top10,

        "full_top_20_features":
            full_top20,

        "Jaccard_at_10_vs_FULL":
            jaccard(
                subset_top10,
                full_top10,
            ),

        "Jaccard_at_20_vs_FULL":
            jaccard(
                subset_top20,
                full_top20,
            ),

        "Spearman_rank_on_common_retained_features":
            spearman_rho,

        "new_top_10_entrants":
            [
                feature
                for feature
                in subset_top10
                if feature
                not in set(
                    full_top10
                )
            ],

        "new_top_20_entrants":
            [
                feature
                for feature
                in subset_top20
                if feature
                not in set(
                    full_top20
                )
            ],

        "features_leaving_top_10":
            [
                feature
                for feature
                in full_top10
                if feature
                not in set(
                    subset_top10
                )
            ],

        "features_leaving_top_20":
            [
                feature
                for feature
                in full_top20
                if feature
                not in set(
                    subset_top20
                )
            ],

        "rank_displacement":
            rank_displacement,

        "normalized_importance_share_change":
            normalized_share_change,

        "top_importance_gainers_after_removal":
            [
                {
                    "feature":
                        feature,

                    "normalized_importance_share_change":
                        normalized_share_change[
                            feature
                        ],

                    "full_rank":
                        int(
                            full_rank[
                                feature
                            ]
                        ),

                    "subset_rank":
                        int(
                            subset_rank[
                                feature
                            ]
                        ),

                    "rank_displacement":
                        int(
                            rank_displacement[
                                feature
                            ]
                        ),
                }

                for feature
                in positive_gainers
            ],
    }


