def run(
    *args,
    cwd=None,
):

    p = subprocess.run(
        list(
            map(
                str,
                args,
            )
        ),
        cwd=cwd,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def git(
    *args,
):

    return run(
        "git",
        *args,
        cwd=REPO,
    )


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


