def git(*args, check=True):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    out = (p.stdout or "").strip()

    if check and p.returncode != 0:
        raise RuntimeError(
            f"git {' '.join(map(str,args))} failed:\n{out}"
        )

    return p.returncode, out


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            block = f.read(chunk)

            if not block:
                break

            h.update(block)

    return h.hexdigest()


def parse_manifest(path):

    out = {}

    for line in Path(path).read_text(
        encoding="utf-8"
    ).splitlines():

        if not line.strip():
            continue

        digest, rel = line.split(
            maxsplit=1
        )

        out[rel.strip()] = digest.strip()

    return out


def candidate_columns(columns):

    hits = []

    keywords = [
        "label",
        "class",
        "attack",
        "family",
        "category",
        "day",
        "row",
        "index",
        "position",
        "binary",
    ]

    for col in columns:

        lower = col.lower()

        if any(
            keyword in lower
            for keyword in keywords
        ):
            hits.append(col)

    return hits


