# =============================================================================
# 1. HELPERS
# =============================================================================

def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (p.stdout or "").strip()


def normalize_label_series(series):

    return (
        series
        .astype(str)
        .str.replace(
            "\ufeff",
            "",
            regex=False,
        )
        .str.strip()
    )


def labels_to_binary(labels):

    labels = np.asarray(
        labels,
        dtype=object,
    )

    out = np.ones(
        len(labels),
        dtype=np.int8,
    )

    for i, value in enumerate(labels):

        text = str(
            value
        ).strip()

        upper = text.upper()

        if upper == "BENIGN":

            out[i] = 0

        elif upper == "LABEL":

            # Embedded header.
            out[i] = -1

        else:

            # Every non-BENIGN traffic category is attack.
            out[i] = 1

    return out


# =============================================================================
# 2. SEALED STATE
# =============================================================================

print("=" * 110)
print("STAGE23-6B2 — DECISIVE original_row_index SEMANTICS RESOLUTION")
print("=" * 110)
