# =============================================================================
# 1. HELPERS
# =============================================================================

def utc_now():
    return datetime.now(
        timezone.utc
    ).isoformat()


def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:
        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def normalize_label_array(values):

    return np.asarray(
        [
            str(x)
            .replace("\ufeff", "")
            .strip()

            for x in values
        ],
        dtype=object,
    )


def labels_to_binary(
    labels,
):

    out = np.empty(
        len(labels),
        dtype=np.int8,
    )

    for i, value in enumerate(
        labels
    ):

        text = (
            str(value)
            .replace("\ufeff", "")
            .strip()
        )

        upper = text.upper()

        if upper == "BENIGN":
            out[i] = 0

        elif upper == "LABEL":
            out[i] = -1

        else:
            out[i] = 1

    return out


def extract_target_labels(
    csv_path,
    target_original_indices,
    expected_physical_rows,
):

    """
    Stream ONLY Label through the authoritative source CSV.

    target_original_indices are proven PHYSICAL zero-based CSV data-row
    indices, excluding the top-level CSV header line.
    """

    targets = np.asarray(
        target_original_indices,
        dtype=np.int64,
    )

    if len(targets) == 0:

        return np.empty(
            0,
            dtype=object,
        )


    if not np.all(
        np.diff(
            targets
        ) > 0
    ):

        raise RuntimeError(
            f"{csv_path.name}: target indices are not strictly increasing."
        )


    if targets[0] < 0:

        raise RuntimeError(
            f"{csv_path.name}: negative target locator."
        )


    recovered = np.empty(
        len(targets),
        dtype=object,
    )

    filled = np.zeros(
        len(targets),
        dtype=bool,
    )

    physical_row_base = 0


    reader = pd.read_csv(
        csv_path,
        usecols=[
            "Label"
        ],
        dtype=str,
        encoding="utf-8-sig",
        keep_default_na=False,
        na_filter=False,
        chunksize=CHUNK_ROWS,
        low_memory=False,
    )


    for chunk in reader:

        n = len(
            chunk
        )

        start = physical_row_base
        stop = start + n


        left = int(
            np.searchsorted(
                targets,
                start,
                side="left",
            )
        )

        right = int(
            np.searchsorted(
                targets,
                stop,
                side="left",
            )
        )


        if right > left:

            wanted = targets[
                left:right
            ]

            local = (
                wanted
                - start
            ).astype(
                np.int64
            )


            chunk_labels = normalize_label_array(
                chunk[
                    "Label"
                ].to_numpy(
                    dtype=object
                )
            )


            recovered[
                left:right
            ] = chunk_labels[
                local
            ]

            filled[
                left:right
            ] = True


        physical_row_base = stop


    if physical_row_base != int(
        expected_physical_rows
    ):

        raise RuntimeError(
            f"{csv_path.name}: physical row-count mismatch.\n"
            f"expected={expected_physical_rows}\n"
            f"actual={physical_row_base}"
        )


    if not np.all(
        filled
    ):

        missing = targets[
            ~filled
        ]

        raise RuntimeError(
            f"{csv_path.name}: failed to recover "
            f"{len(missing)} requested source rows.\n"
            f"first missing={missing[:10].tolist()}"
        )


    return recovered


