def utc_now():

    return datetime.now(
        timezone.utc
    ).isoformat()


def git(*args):

    p = subprocess.run(
        ["git", *map(str, args)],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=os.environ.copy(),
    )

    if p.returncode != 0:

        raise RuntimeError(
            p.stdout
        )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            b = f.read(chunk)

            if not b:
                break

            h.update(b)

    return h.hexdigest()


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def safe_json(v):

    if v is None:
        return None

    if isinstance(
        v,
        (bool, np.bool_),
    ):
        return bool(v)

    if isinstance(
        v,
        (int, np.integer),
    ):
        return int(v)

    if isinstance(
        v,
        (float, np.floating),
    ):

        x = float(v)

        if not math.isfinite(x):
            return None

        return x

    return str(v)


def records_json_safe(df):

    return [
        {
            k: safe_json(v)
            for k, v in row.items()
        }
        for row in df.to_dict(
            orient="records"
        )
    ]


def expected_sha_from_manifest(
    artifact_path,
):

    manifest_path = (
        artifact_path.parent
        / "checksums.sha256"
    )

    if not manifest_path.is_file():

        raise RuntimeError(
            "Sibling checksum manifest missing:\n"
            f"{manifest_path}"
        )


    matches = []


    for line in manifest_path.read_text(
        encoding="utf-8"
    ).splitlines():

        if not line.strip():
            continue

        digest, rel = line.split(
            maxsplit=1
        )

        if Path(
            rel.strip()
        ).name == artifact_path.name:

            matches.append(
                digest.strip()
            )


    if len(matches) != 1:

        raise RuntimeError(
            "Could not uniquely resolve frozen SHA:\n"
            f"{artifact_path}\n"
            f"matches={len(matches)}"
        )


    return matches[0]


def verify_probability_artifact(
    path,
    expected_sha=None,
):

    if not path.is_file():

        raise RuntimeError(
            f"Probability artifact missing:\n{path}"
        )


    if expected_sha is None:

        expected_sha = (
            expected_sha_from_manifest(
                path
            )
        )


    actual = sha256_file(
        path
    )


    if actual != expected_sha:

        raise RuntimeError(
            "Probability artifact SHA mismatch:\n"
            f"{path}\n"
            f"expected={expected_sha}\n"
            f"actual={actual}"
        )


    return actual


def load_probability_npz(
    path,
):

    with np.load(
        path,
        allow_pickle=False,
    ) as z:

        required = {
            "clean_position",
            "binary_label",
            "ensemble_probability",
        }


        if not required.issubset(
            set(z.files)
        ):

            raise RuntimeError(
                f"{path.name}: required NPZ keys missing.\n"
                f"keys={sorted(z.files)}"
            )


        clean = np.asarray(
            z["clean_position"],
            dtype=np.int64,
        ).copy()


        y = np.asarray(
            z["binary_label"],
            dtype=np.int8,
        ).copy()


        raw_probability = z[
            "ensemble_probability"
        ]


        if raw_probability.dtype != np.float32:

            raise RuntimeError(
                f"{path.name}: probability storage dtype "
                f"is {raw_probability.dtype}, expected float32."
            )


        probability = np.asarray(
            raw_probability,
            dtype=np.float32,
        ).copy()


    if not (
        len(clean)
        == len(y)
        == len(probability)
    ):

        raise RuntimeError(
            f"{path.name}: vector length mismatch."
        )


    if not np.all(
        np.isin(
            y,
            [0, 1],
        )
    ):

        raise RuntimeError(
            f"{path.name}: non-binary labels."
        )


    if not np.all(
        np.isfinite(
            probability
        )
    ):

        raise RuntimeError(
            f"{path.name}: non-finite probabilities."
        )


    if (
        probability.min() < 0.0
        or probability.max() > 1.0
    ):

        raise RuntimeError(
            f"{path.name}: probability outside [0,1]."
        )


    return (
        clean,
        y,
        probability,
    )


