# 2. EXACT RANKING METRICS
# =============================================================================

def fast_family_ranking_metrics(
    benign_sorted,
    attack_scores,
):

    B = int(
        len(benign_sorted)
    )

    P = int(
        len(attack_scores)
    )


    if B <= 0:

        raise RuntimeError(
            "No benign validation rows."
        )


    if P == 0:

        return (
            np.nan,
            np.nan,
        )


    attack_scores = np.asarray(
        attack_scores,
        dtype=np.float32,
    )


    # ROC-AUC.
    left = np.searchsorted(
        benign_sorted,
        attack_scores,
        side="left",
    )

    right = np.searchsorted(
        benign_sorted,
        attack_scores,
        side="right",
    )


    wins = (
        left.astype(np.float64)
        +
        0.5
        * (
            right
            - left
        ).astype(np.float64)
    )


    roc_auc = float(
        np.sum(
            wins,
            dtype=np.float64,
        )
        /
        (
            float(P)
            * float(B)
        )
    )


    # Average precision / PR-AUC.
    unique_scores, counts = np.unique(
        attack_scores,
        return_counts=True,
    )


    score_desc = unique_scores[::-1]

    count_desc = counts[
        ::-1
    ].astype(
        np.int64
    )


    tp_cumulative = np.cumsum(
        count_desc,
        dtype=np.int64,
    )


    fp_cumulative = (
        B
        -
        np.searchsorted(
            benign_sorted,
            score_desc,
            side="left",
        )
    ).astype(
        np.int64
    )


    precision = (
        tp_cumulative.astype(
            np.float64
        )
        /
        (
            tp_cumulative
            + fp_cumulative
        ).astype(
            np.float64
        )
    )


    recall_increment = (
        count_desc.astype(
            np.float64
        )
        / float(P)
    )


    pr_auc = float(
        np.sum(
            recall_increment
            * precision,
            dtype=np.float64,
        )
    )


    return (
        pr_auc,
        roc_auc,
    )


def frozen_operating_metrics(
    benign_scores,
    attack_scores,
):

    B = int(
        len(benign_scores)
    )

    P = int(
        len(attack_scores)
    )


    fp = int(
        np.sum(
            benign_scores
            >= THRESHOLD
        )
    )


    fpr = (
        float(fp / B)
        if B > 0
        else np.nan
    )


    # No family-A attacks in this validation split.
    if P == 0:

        return {
            "precision_at_0_50":
                np.nan,

            "recall_at_0_50":
                np.nan,

            "f1_at_0_50":
                np.nan,

            "fpr_at_0_50":
                fpr,

            "fnr_at_0_50":
                np.nan,
        }


    tp = int(
        np.sum(
            attack_scores
            >= THRESHOLD
        )
    )


    fn = (
        P
        - tp
    )


    precision = (
        float(
            tp
            / (
                tp
                + fp
            )
        )
        if (
            tp
            + fp
        ) > 0
        else 0.0
    )


    recall = float(
        tp
        / P
    )


    f1 = (
        float(
            2.0
            * precision
            * recall
            / (
                precision
                + recall
            )
        )
        if (
            precision
            + recall
        ) > 0
        else 0.0
    )


    fnr = float(
        fn
        / P
    )


    return {
        "precision_at_0_50":
            precision,

        "recall_at_0_50":
            recall,

        "f1_at_0_50":
            f1,

        "fpr_at_0_50":
            fpr,

        "fnr_at_0_50":
            fnr,
    }


