def utc_now():

    return datetime.now(
        timezone.utc
    ).isoformat()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open("rb") as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        ) + "\n",
        encoding="utf-8",
    )


def git(
    *args,
    check=True,
    env=None,
    show=False,
):

    merged_env = os.environ.copy()

    if env:
        merged_env.update(
            env
        )


    p = subprocess.run(
        [
            "git",
            *map(
                str,
                args,
            ),
        ],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=merged_env,
    )


    output = (
        p.stdout
        or ""
    ).strip()


    if show and output:
        print(output)


    if (
        check
        and p.returncode != 0
    ):

        raise RuntimeError(
            f"git {' '.join(map(str, args))} failed:\n"
            f"{output}"
        )


    return (
        p.returncode,
        output,
    )


def verify_manifest(
    root,
    manifest_path,
):

    count = 0


    for line in Path(
        manifest_path
    ).read_text(
        encoding="utf-8"
    ).splitlines():

        if not line.strip():
            continue


        digest, relative = line.split(
            maxsplit=1
        )


        relative = relative.strip()

        path = (
            root
            / relative
        )


        if not path.is_file():

            raise RuntimeError(
                "Checksum manifest references missing file:\n"
                f"{path}"
            )


        actual = sha256_file(
            path
        )


        if actual != digest:

            raise RuntimeError(
                "Checksum mismatch:\n"
                f"{relative}\n"
                f"expected={digest}\n"
                f"actual={actual}"
            )


        count += 1


    return count


def verify_named_hashes(
    root,
    expected,
):

    for name, digest in expected.items():

        path = (
            root
            / name
        )


        if not path.is_file():

            raise RuntimeError(
                f"Required artifact missing:\n{path}"
            )


        actual = sha256_file(
            path
        )


        print(name)
        print(
            "  expected:",
            digest,
        )
        print(
            "  actual:  ",
            actual,
        )


        if actual != digest:

            raise RuntimeError(
                f"SHA mismatch: {name}"
            )


        print("  [EXACT]")


def copy_tree_exact(
    source,
    destination,
):

    if destination.exists():

        raise RuntimeError(
            "Destination already exists:\n"
            f"{destination}"
        )


    shutil.copytree(
        source,
        destination,
        copy_function=shutil.copy2,
    )


