# ==================================================================================================
# HELPERS
# ==================================================================================================

def git(*args: str) -> str:
    p = subprocess.run(
        ["git", *args],
        cwd=REPO,
        check=True,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    return p.stdout.strip()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def write_json(path: Path, obj) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(obj, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )


def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.rstrip() + "\n", encoding="utf-8")


SOURCE_FILES: dict[str, str] = {}


def register_source(path: Path) -> None:
    assert path.is_file(), f"Missing source: {path}"
    rel = str(path.relative_to(REPO))
    SOURCE_FILES[rel] = sha256_file(path)


def read_json(path: Path):
    register_source(path)
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def read_csv(path: Path) -> pd.DataFrame:
    register_source(path)
    return pd.read_csv(path)


def f6(x) -> str:
    if x is None:
        return ""
    try:
        if pd.isna(x):
            return ""
    except Exception:
        pass
    return f"{float(x):.6f}"


def f4(x) -> str:
    if x is None:
        return ""
    try:
        if pd.isna(x):
            return ""
    except Exception:
        pass
    return f"{float(x):.4f}"


def signed6(x) -> str:
    return f"{float(x):+.6f}"


def ci_excludes_zero(low: float, high: float) -> bool:
    return bool(low > 0.0 or high < 0.0)


def latex_escape(s: str) -> str:
    s = str(s)
    replacements = [
        ("\\", r"\textbackslash{}"),
        ("&", r"\&"),
        ("%", r"\%"),
        ("$", r"\$"),
        ("#", r"\#"),
        ("_", r"\_"),
        ("{", r"\{"),
        ("}", r"\}"),
        ("~", r"\textasciitilde{}"),
        ("^", r"\textasciicircum{}"),
    ]
    for a, b in replacements:
        s = s.replace(a, b)
    return s


def save_figure(fig, stem: Path) -> None:
    stem.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(stem.with_suffix(".png"), dpi=300, bbox_inches="tight")
    fig.savefig(stem.with_suffix(".pdf"), bbox_inches="tight")
    plt.close(fig)


def row_for(df: pd.DataFrame, split: str, subset: str) -> pd.Series:
    x = df[(df["split"] == split) & (df["subset"] == subset)]
    assert len(x) == 1, (split, subset, len(x))
    return x.iloc[0]


