def git(*args):

    p = subprocess.run(
        ["git", *args],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        check=True,
    )

    return (
        p.stdout or ""
    ).strip()


def sha256_file(
    path,
    chunk=1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


SOURCE_FILES = {}


def register_source(
    path,
):

    path = Path(
        path
    )

    if not path.is_file():

        raise RuntimeError(
            f"Missing sealed source:\n{path}"
        )


    rel = str(
        path.relative_to(
            REPO
        )
    )


    SOURCE_FILES[
        rel
    ] = sha256_file(
        path
    )


def read_json(
    path,
):

    register_source(
        path
    )

    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def read_csv(
    path,
):

    register_source(
        path
    )

    return pd.read_csv(
        path
    )


def write_json(
    path,
    obj,
):

    Path(path).parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
        + "\n",
        encoding="utf-8",
    )


def write_text(
    path,
    text,
):

    Path(path).parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    Path(path).write_text(
        str(text).rstrip()
        + "\n",
        encoding="utf-8",
    )


def ci_excludes_zero(
    low,
    high,
):

    return bool(
        float(low) > 0.0
        or float(high) < 0.0
    )


def row_for(
    df,
    split,
    subset,
):

    g = df[
        (
            df[
                "split"
            ]
            == split
        )
        &
        (
            df[
                "subset"
            ]
            == subset
        )
    ]


    if len(
        g
    ) != 1:

        raise RuntimeError(
            f"Row not unique: {split}/{subset}; n={len(g)}"
        )


    return g.iloc[
        0
    ]


def save_figure(
    fig,
    stem,
):

    stem.parent.mkdir(
        parents=True,
        exist_ok=True,
    )


    fig.savefig(
        stem.with_suffix(
            ".png"
        ),
        dpi=300,
        bbox_inches="tight",
    )


    fig.savefig(
        stem.with_suffix(
            ".pdf"
        ),
        bbox_inches="tight",
    )


    plt.close(
        fig
    )


def latex_escape(
    value,
):

    s = str(
        value
    )

    mapping = [
        ("\\", r"\textbackslash{}"),
        ("&", r"\&"),
        ("%", r"\%"),
        ("$", r"\$"),
        ("#", r"\#"),
        ("_", r"\_"),
        ("{", r"\{"),
        ("}", r"\}"),
    ]


    for a, b in mapping:

        s = s.replace(
            a,
            b,
        )


    return s


