for split in SPLITS:

    full = consensus[
        (
            consensus[
                "split"
            ]
            == split
        )
        &
        (
            consensus[
                "subset"
            ]
            == "FULL"
        )
    ][
        [
            "feature",
            "consensus_normalized_importance_share",
        ]
    ].copy()


    if len(
        full
    ) != 70:

        raise RuntimeError(
            f"{split}: FULL consensus feature count != 70."
        )


    full = full.rename(
        columns={
            "consensus_normalized_importance_share":
                "full_share"
        }
    )


    for subset in PRIMARY_ABLATIONS:

        sub = consensus[
            (
                consensus[
                    "split"
                ]
                == split
            )
            &
            (
                consensus[
                    "subset"
                ]
                == subset
            )
        ][
            [
                "feature",
                "consensus_normalized_importance_share",
            ]
        ].copy()


        merged = sub.merge(
            full,
            on="feature",
            how="inner",
            validate="one_to_one",
        )


        merged[
            "share_change"
        ] = (
            merged[
                "consensus_normalized_importance_share"
            ]
            -
            merged[
                "full_share"
            ]
        )


        merged = merged.sort_values(
            [
                "share_change",
                "feature",
            ],
            ascending=[
                False,
                True,
            ],
        )


        top = merged.iloc[
            0
        ]


        gainer_rows.append(
            {
                "split":
                    split,

                "subset":
                    subset,

                "top_retained_consensus_share_gainer":
                    str(
                        top[
                            "feature"
                        ]
                    ),

                "top_retained_consensus_share_gain":
                    float(
                        top[
                            "share_change"
                        ]
                    ),
            }
        )


