# 17. SUPPLEMENTARY FIGURE S2 — ATTACK-FAMILY ΔF1
# ==================================================================================================

random_families = random_interp[
    "attack_family"
].tolist()


chrono_families = chrono_interp[
    "attack_family"
].tolist()


if chrono_families != [
    "Infilteration"
]:

    raise RuntimeError(
        "Unexpected chronological interpretable family set."
    )


rmat = (
    attack_df[
        (
            attack_df[
                "split"
            ]
            == "RANDOM_NATURAL"
        )
        &
        (
            attack_df[
                "interpretation_status"
            ]
            == "INTERPRETABLE"
        )
        &
        (
            attack_df[
                "subset"
            ].isin(
                PRIMARY_ABLATIONS
            )
        )
    ]
    .pivot(
        index="attack_family",
        columns="subset",
        values="delta_f1_FULL_minus_ablated",
    )
    .reindex(
        index=random_families,
        columns=PRIMARY_ABLATIONS,
    )
)


cmat = (
    attack_df[
        (
            attack_df[
                "split"
            ]
            == "CHRONOLOGICAL_NATURAL"
        )
        &
        (
            attack_df[
                "interpretation_status"
            ]
            == "INTERPRETABLE"
        )
        &
        (
            attack_df[
                "subset"
            ].isin(
                PRIMARY_ABLATIONS
            )
        )
    ]
    .pivot(
        index="attack_family",
        columns="subset",
        values="delta_f1_FULL_minus_ablated",
    )
    .reindex(
        index=chrono_families,
        columns=PRIMARY_ABLATIONS,
    )
)


