def sha256_file(
    path,
    chunk=1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


SOURCE_FILES = {}


def register_source(
    path,
):

    path = Path(
        path
    )


    if not path.is_file():

        raise RuntimeError(
            f"Missing sealed source:\n{path}"
        )


    rel = str(
        path.relative_to(
            REPO
        )
    )


    SOURCE_FILES[
        rel
    ] = sha256_file(
        path
    )


def read_json(
    path,
):

    register_source(
        path
    )

    return json.loads(
        Path(path).read_text(
            encoding="utf-8"
        )
    )


def read_csv(
    path,
):

    register_source(
        path
    )

    return pd.read_csv(
        path
    )


def write_json(
    path,
    obj,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )


    path.write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
        + "\n",
        encoding="utf-8",
    )


def write_text(
    path,
    text,
):

    path = Path(
        path
    )

    path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )


    path.write_text(
        str(
            text
        ).rstrip()
        + "\n",
        encoding="utf-8",
    )


def ci_excludes_zero(
    lo,
    hi,
):

    return bool(
        float(
            lo
        )
        > 0.0

        or

        float(
            hi
        )
        < 0.0
    )


def row_for(
    df,
    split,
    subset,
):

    g = df[
        (
            df[
                "split"
            ]
            == split
        )
        &
        (
            df[
                "subset"
            ]
            == subset
        )
    ]


    if len(
        g
    ) != 1:

        raise RuntimeError(
            f"Row not unique: "
            f"{split}/{subset}; "
            f"n={len(g)}"
        )


    return g.iloc[
        0
    ]


def save_figure(
    fig,
    stem,
):

    stem = Path(
        stem
    )

    stem.parent.mkdir(
        parents=True,
        exist_ok=True,
    )


    fig.savefig(
        stem.with_suffix(
            ".png"
        ),
        dpi=300,
        bbox_inches="tight",
    )


    fig.savefig(
        stem.with_suffix(
            ".pdf"
        ),
        bbox_inches="tight",
    )


    plt.close(
        fig
    )


def latex_escape(
    value,
):

    s = str(
        value
    )


    for src, dst in [
        ("\\", r"\textbackslash{}"),
        ("&", r"\&"),
        ("%", r"\%"),
        ("$", r"\$"),
        ("#", r"\#"),
        ("_", r"\_"),
        ("{", r"\{"),
        ("}", r"\}"),
    ]:

        s = s.replace(
            src,
            dst,
        )


    return s


