def utc_now():

    return datetime.now(
        timezone.utc
    ).isoformat()


def sha256_file(
    path,
    chunk=32 * 1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


def write_json(
    path,
    obj,
):

    Path(path).write_text(
        json.dumps(
            obj,
            indent=2,
            sort_keys=True,
            allow_nan=False,
        )
        + "\n",
        encoding="utf-8",
    )


def git(
    *args,
    check=True,
    env=None,
    show=False,
):

    merged_env = os.environ.copy()

    if env:

        merged_env.update(
            env
        )


    p = subprocess.run(
        [
            "git",
            *map(
                str,
                args,
            ),
        ],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=merged_env,
    )


    output = (
        p.stdout
        or ""
    ).strip()


    if (
        check
        and p.returncode != 0
    ):

        raise RuntimeError(
            "git command failed:\n"
            f"git {' '.join(map(str, args))}\n"
            f"{output}"
        )


    if (
        show
        and output
    ):

        print(
            output
        )


    return (
        p.returncode,
        output,
    )


def verify_checksum_manifest(
    root,
    manifest,
):

    lines = Path(
        manifest
    ).read_text(
        encoding="utf-8"
    ).splitlines()


    entries = []


    for line in lines:

        if not line.strip():

            continue


        digest, rel = line.split(
            "  ",
            1,
        )


        target = (
            Path(root)
            / rel
        )


        if not target.is_file():

            raise RuntimeError(
                "Checksum manifest target missing:\n"
                f"{target}"
            )


        actual = sha256_file(
            target
        )


        if actual != digest:

            raise RuntimeError(
                "Checksum mismatch:\n"
                f"{rel}\n"
                f"expected={digest}\n"
                f"actual={actual}"
            )


        entries.append(
            (
                digest,
                rel,
            )
        )


    return entries


