def git(
    *args,
    check=True,
    env=None,
    show=False,
):

    merged_env = os.environ.copy()

    if env:
        merged_env.update(
            env
        )

    p = subprocess.run(
        [
            "git",
            *map(str, args),
        ],
        cwd=REPO,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        env=merged_env,
    )

    output = (
        p.stdout
        or ""
    ).strip()

    if (
        check
        and p.returncode != 0
    ):
        raise RuntimeError(
            f"git {' '.join(map(str, args))} failed:\n"
            f"{output}"
        )

    if (
        show
        and output
    ):
        print(output)

    return (
        p.returncode,
        output,
    )


def sha256_file(
    path,
    chunk=1024 * 1024,
):

    h = hashlib.sha256()

    with Path(path).open(
        "rb"
    ) as f:

        while True:

            b = f.read(
                chunk
            )

            if not b:
                break

            h.update(
                b
            )

    return h.hexdigest()


